SELECT id, product_id, unit_price, MAX(quantity) OVER (PARTITION BY order_id) AS order_id_max_quantity, CORR(unit_price, quantity) OVER (PARTITION BY product_id) AS corr_unit_price_quantity, ROW_NUMBER() OVER (ORDER BY quantity DESC, id) AS seq_no, AVG(quantity) OVER (PARTITION BY order_id) AS order_id_avg_quantity, ROW_NUMBER() OVER (ORDER BY unit_price, id) AS event_seq FROM order_items WHERE unit_price >= 170;
